// Loading moderno reutilizável (anel girando com a cor da barra)
function ccmShowLoading() {
    $.LoadingOverlay("show", {
        image: "",
        custom: '<div class="ccm-spinner"></div>',
        // No Safari/iOS o auto-resize do plugin mede o elemento antes do
        // layout e acaba zerando o tamanho do spinner (fica invisível).
        // Desligamos para respeitar o tamanho fixo definido no CSS.
        customAutoResize: false,
        // Sem fade-in: por padrão o plugin faz fadeTo(400ms). Como a
        // navegação ocorre logo em seguida, no Safari o overlay congelava
        // quase transparente e parecia não aparecer. Exibe instantâneo.
        fade: false,
        background: "rgba(23,23,23,.65)",
        zIndex: 99999999
    });
}

function navegarComOverlay(url, replace = false)
{
    // Quando é App nativo - já tem um Loading
    if (inWebviewJs() == false)
    {
        ccmShowLoading();
    }

    var irPara = function () {
        if (replace)
            window.location.replace(url);
        else
            window.location.href = url;
    };

    // Safari/iOS descarta o frame de paint pendente ao iniciar a navegação,
    // então o requestAnimationFrame não chega a pintar o spinner. Nesses
    // browsers usamos um pequeno timeout (suficiente para pintar, bem menor
    // que os 225ms antigos). Nos demais, 2x rAF navega assim que o spinner
    // é pintado (~16-33ms), mantendo o clique bem responsivo.
    if (isAppleWebKit) {
        setTimeout(irPara, 60);
    } else {
        requestAnimationFrame(function () {
            requestAnimationFrame(irPara);
        });
    }

    setTimeout(function(){
        $.LoadingOverlay("hide");
    }, 3000);
}

