// Detecta quando a página é carregada via history back
window.addEventListener('pageshow', function(event) {
    hideOverlayRobust();

    // Para iOS Safari, adiciona um delay extra
    if (isIOSSafari) {
        setTimeout(hideOverlayRobust, 100);
    }
});

// Detecta mudanças de visibilidade (importante para iOS)
document.addEventListener('visibilitychange', function() {
    if (!document.hidden) {
        hideOverlayRobust();
    }
});

// Detecta quando a página recebe foco (fallback para iOS)
window.addEventListener('focus', function() {
    hideOverlayRobust();
});

// Limpa o overlay quando sair da página
window.addEventListener('pagehide', function() {
    hideOverlayRobust();
});

